import math
nx = input().split(' ')
(n, x) = (int(nx[0]), int(nx[1]))
a = list(map(int, input().split(' ')))
a.sort()
(failed, success) = (n, 0)
for i in range(n):
	if x - math.ceil(a[i] / 2) >= 0:
		failed -= 1
		x -= math.ceil(a[i] / 2)
		a[i] -= math.ceil(a[i] / 2)
	else:
		break
for i in range(n):
	if x - a[i] >= 0:
		success += 1
		x -= a[i]
	else:
		break
print('{} {}'.format(failed, success))
